*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gEduApplSeq;
scwin.gEcrDiptProcsStatCd;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no; // 세션정보 	
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 



scwin.gPROCS_CD = '';
scwin.V_PROCS_CD_1 = '1'; //검토
scwin.V_PROCS_CD_2 = '2'; //승인
scwin.V_PROCS_CD_3 = '3'; //유보


scwin.vScrenID = "ULDSTF16516.xml";
scwin.edu_appl_seq = frame.opener.scwin.edu_appl_seq;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Read = function() {
    //공문 개별조회


    url = "/ListedCompany.do?method=readLecrDispatch&EDU_APPL_SEQ=" + scwin.edu_appl_seq + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Master.DataID = encodeURI(url);
    dts_Master.reset();

    //교육기간
    url = "/ListedCompany.do?method=readLecrDispEduSchdl" + "&EDU_APPL_SEQ=" + scwin.edu_appl_seq + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_EDU_SCHDL.DataID = encodeURI(url);
    dts_EDU_SCHDL.reset();
};


// 처리버튼 생성여부 
scwin.fn_showProcButton = function(pEcrDiptProcsStatCd, pEduApplSeq, pProcsDepCd) {
    scwin.gEcrDiptProcsStatCd = pEcrDiptProcsStatCd;
    scwin.gEduApplSeq = pEduApplSeq;
    btn_Revwr.src = "../img/btn_study_d.gif";
    btn_Revwr.setDisabled(true);
    btn_Approve.src = "../img/btn_approval_d.gif";
    btn_Approve.setDisabled(true);
    btn_Reject.src = "../img/btn_reserve_d.gif";
    btn_Reject.setDisabled(true);
    $c.stf.showObj(panel_Button, false);
    if (scwin.gEduApplSeq != '') {
        //00:미처리,10:검토,30:승인,40:유보
        if (scwin.gEcrDiptProcsStatCd == '00') {
            $c.stf.showObj(panel_Button, true);
            // 팀장,당번 권한, 담당 부서원  팀장  : 09,   부서장: 40, 팀원: 03
            if (scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y' || scwin.gJobTitle == '09') {
                btn_Revwr.src = "../img/btn_study.gif";
                btn_Revwr.setDisabled(false);
                btn_Reject.src = "../img/btn_reserve.gif";
                btn_Reject.setDisabled(false);
            } else if (scwin.gDepCd == pProcsDepCd) {
                btn_Revwr.src = "../img/btn_study.gif";
                btn_Revwr.setDisabled(false);
                btn_Reject.src = "../img/btn_reserve.gif";
                btn_Reject.setDisabled(false);
            } else {
                $c.stf.showObj(panel_Button, false);
            }
        } else if (scwin.gEcrDiptProcsStatCd == '10') {
            $c.stf.showObj(panel_Button, true);

            // 팀장,당번 권한  팀장  : 09,   부서장: 40, 팀원: 03
            if (scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y' || scwin.gJobTitle == '09') {
                btn_Approve.src = "../img/btn_approval.gif";
                btn_Approve.setDisabled(false);
                btn_Reject.src = "../img/btn_reserve.gif";
                btn_Reject.setDisabled(false);
            } else {
                $c.stf.showObj(panel_Button, false);
            }
        } else {
            $c.stf.showObj(panel_Button, false);
        }
    }
};




// 검토
scwin.fn_Revwr = function() {
    scwin.fn_Save('10');
};


// 승인
scwin.fn_Approve = function() {
    scwin.fn_Save('30');
};


// 유보
scwin.fn_Reject = function() {
    scwin.fn_Save('40');
};
scwin.fn_Save = function(pType) {
    var gMSG = '';
    if (pType == '10') {
        scwin.gPROCS_CD = scwin.V_PROCS_CD_1;
        gMSG = '검토';
    } else if (pType == '30') {
        scwin.gPROCS_CD = scwin.V_PROCS_CD_2;
        gMSG = '승인';
    } else if (pType == '40') {
        scwin.gPROCS_CD = scwin.V_PROCS_CD_3;
        gMSG = '유보';
    }
    var rtn = confirm(gMSG + ' 처리 하시겠습니까?');
    if (rtn == 1) {
        //if ( fn_getProcsSate(gPROCS_CD) == false ) {
        //	return false;
        //} else {
        trs_Approve.Action = "/ListedCompany.do?method=approveLecProcsStat" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Approve.KeyName = "toinb_dataid4";
        trs_Approve.KeyValue = "JSP(I:pInput=dts_Master)";
        trs_Approve.Parameters = "EDU_APPL_SEQ=" + scwin.gEduApplSeq + ",LECR_DIPT_PROCS_STAT_CD=" + pType + ",EMP_NO=" + js_emp_no;
        trs_Approve.Post();
        //}

    }
};
scwin.dts_Master_OnLoadCompleted = function(rowcount) {
    //fn_showProcButton( dts_Item.NameString(1, "HDCOM_DEP_CD" ), dts_Item.NameString(1, "LNK_DISCLS_PROCS_STAT_CD" ) );	
    scwin.fn_showProcButton(dts_Master.getCellData(1, "LECR_DIPT_PROCS_STAT_CD"), dts_Master.getCellData(1, "EDU_APPL_SEQ"), dts_Master.getCellData(1, "DEP_CD"));
};
scwin.btn_Cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Approve_OnSuccess = function() {
    $c.win.alert('정상처리되었습니다');
    scwin.fn_Read();
    $c.frame.path("../").fn_Search();
};
scwin.trs_Approve_OnFail = function() {
    $c.win.alert('처리가 실패하였습니다');
    $c.win.alert(trs_Approve.ErrorMsg);
};
scwin.btn_Revwr_onclick = function() {
    scwin.fn_Revwr();
};
scwin.btn_Approve_onclick = function() {
    scwin.fn_Approve();
};
scwin.btn_Reject_onclick = function() {
    scwin.fn_Reject();
};
scwin.gform_onload = function() {
    frame.width = 720;
    frame.height = 550;
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.fn_Read();
};
